--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `courses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ciclo` int NOT NULL,
  `modalidad` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PRS',
  `alumnos_teoria` int DEFAULT NULL,
  `alumnos_practica` int DEFAULT NULL,
  `alumnos_laboratorio` int DEFAULT NULL,
  `grupos_teoria` int DEFAULT NULL,
  `grupos_practica` int DEFAULT NULL,
  `grupos_laboratorio` int DEFAULT NULL,
  `requiere_laboratorio` tinyint(1) DEFAULT NULL,
  `requiere_practica` tinyint(1) DEFAULT NULL,
  `creditos` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_courses_codigo` (`codigo`),
  KEY `ix_courses_ciclo` (`ciclo`),
  KEY `idx_course_ciclo_modalidad` (`ciclo`,`modalidad`)
) ENGINE=InnoDB AUTO_INCREMENT=688 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

