--
-- Table structure for table `professor_course_assignments`
--

DROP TABLE IF EXISTS `professor_course_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `professor_course_assignments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `professor_id` int NOT NULL,
  `course_id` int NOT NULL,
  `session_type` enum('teoria','practica','laboratorio') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `league` int NOT NULL DEFAULT '1',
  `semestre` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '2025-20',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_course_league_session_professor` (`course_id`,`league`,`session_type`,`professor_id`),
  UNIQUE KEY `unique_assignment` (`professor_id`,`course_id`,`session_type`,`league`,`semestre`),
  KEY `idx_professor` (`professor_id`),
  KEY `idx_course` (`course_id`),
  KEY `idx_session_type` (`session_type`),
  CONSTRAINT `professor_course_assignments_ibfk_1` FOREIGN KEY (`professor_id`) REFERENCES `professors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `professor_course_assignments_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2479 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

