DROP TABLE IF EXISTS `schedule_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule_assignments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `course_id` int NOT NULL,
  `course_section_id` int NOT NULL,
  `professor_id` int NOT NULL,
  `classroom_id` int DEFAULT NULL,
  `time_slot_id` int DEFAULT NULL,
  `semestre` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generado_por_algoritmo` tinyint(1) DEFAULT NULL,
  `confianza_asignacion` float DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `course_id` (`course_id`),
  KEY `course_section_id` (`course_section_id`),
  KEY `professor_id` (`professor_id`),
  KEY `classroom_id` (`classroom_id`),
  KEY `time_slot_id` (`time_slot_id`),
  KEY `idx_schedule_semestre_curso` (`semestre`,`course_id`),
  CONSTRAINT `schedule_assignments_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`),
  CONSTRAINT `schedule_assignments_ibfk_2` FOREIGN KEY (`course_section_id`) REFERENCES `course_sections` (`id`),
  CONSTRAINT `schedule_assignments_ibfk_3` FOREIGN KEY (`professor_id`) REFERENCES `professors` (`id`),
  CONSTRAINT `schedule_assignments_ibfk_4` FOREIGN KEY (`classroom_id`) REFERENCES `classrooms` (`id`),
  CONSTRAINT `schedule_assignments_ibfk_5` FOREIGN KEY (`time_slot_id`) REFERENCES `time_slots` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2563 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
